import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"Forge Tool API 接入契约","description":"","frontmatter":{},"headers":[],"relativePath":"forge/README_zh.md","filePath":"forge/README_zh.md"}'),i={name:"forge/README_zh.md"};function s(l,e,d,c,r,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="forge-tool-api-接入契约" tabindex="-1">Forge Tool API 接入契约 <a class="header-anchor" href="#forge-tool-api-接入契约" aria-label="Permalink to &quot;Forge Tool API 接入契约&quot;">​</a></h1><p><a href="/docs/forge/README">English</a> · <a href="/docs/">文档索引</a></p><blockquote><p>适用于 PhyAgentOS 1.0.0。</p></blockquote><h2 id="_1-执行边界" tabindex="-1">1. 执行边界 <a class="header-anchor" href="#_1-执行边界" aria-label="Permalink to &quot;1. 执行边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>绑定 AgentTask 的调用 / 诊断 Query</span></span>
<span class="line"><span>        → ForgeToolClient</span></span>
<span class="line"><span>        → Gateway /tools → ToolInvocation → ToolEndpoint</span></span>
<span class="line"><span>        → Dora 与机器人节点</span></span></code></pre></div><p>PAOS 支持 Query、Action 与 Session。AgentTask 聚合用户目标，但 Gateway 仍是物理执行所有者。 诊断 Query 可以不创建任务；Action 与 task-owned Session 必须使用冻结的 AgentTask binding。 所选 Endpoint operation 执行 <code>max_concurrency</code>；PAOS 不增加跨 Tool Resource/Control lease。</p><h2 id="_2-tool-发现与-context" tabindex="-1">2. Tool 发现与 context <a class="header-anchor" href="#_2-tool-发现与-context" aria-label="Permalink to &quot;2. Tool 发现与 context&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /tools</span></span>
<span class="line"><span>GET /tools/{tool_id}</span></span>
<span class="line"><span>GET /tools/{tool_id}/context</span></span></code></pre></div><p>ToolSpec 声明稳定 identity、implementation/Endpoint binding、operation、<code>query|action|session</code> semantics、严格 input/output schema、readiness 与 robot frame profile。调用前实时读取 context， 调用方不能猜测 frame、unit、readiness 或 binding。</p><h2 id="_3-query-契约" tabindex="-1">3. Query 契约 <a class="header-anchor" href="#_3-query-契约" aria-label="Permalink to &quot;3. Query 契约&quot;">​</a></h2><p><code>forge_tool_query</code> 读取配置 ToolSpec，确认 <code>semantics=query</code>，再调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /tools/{endpoint_id}/{operation}:invoke</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;arguments&quot;: {},</span></span>
<span class="line"><span>  &quot;caller_id&quot;: &quot;paos:&lt;task-or-diagnostic-identity&gt;&quot;,</span></span>
<span class="line"><span>  &quot;timeout_ms&quot;: 10000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>成功响应为 HTTP 200 和 <code>{ &quot;ok&quot;: true, &quot;data&quot;: { ... } }</code>。caller ID 由 PAOS 生成。绑定 Query 在 active PlanRevision 下创建终态 PAOS ToolExecutionRecord；无任务 Query 返回相同 Gateway data，但不 进行任务归因。</p><h2 id="_4-action-契约" tabindex="-1">4. Action 契约 <a class="header-anchor" href="#_4-action-契约" aria-label="Permalink to &quot;4. Action 契约&quot;">​</a></h2><p>Admission：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /tools/{tool_id}:invoke</span></span>
<span class="line"><span>→ HTTP 202</span></span>
<span class="line"><span>→ data.invocation_id + data.attempt_id</span></span></code></pre></div><p>Reconciliation：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /invocations/{invocation_id}</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}/result</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/cancel</span></span></code></pre></div><p>Result HTTP 202 表示 pending。Cancel HTTP 200/202 表示取消请求已处理或接受，不证明停止。 Timeout 表示远端状态未知。显式 <code>unknown</code> 终态会以失败关闭 PAOS 记账，但物理效果仍不确定， 不能触发盲目重试。</p><p>PAOS 在 admission 前持久化 Action intent 与生成的 caller ID，并保留 Gateway 返回的每个 invocation/attempt identity。Timeout 或传输错误形成 <code>unknown</code> record；恢复只能读取已持久化 invocation ID，绝不盲目重复 POST。</p><h2 id="_5-session-契约" tabindex="-1">5. Session 契约 <a class="header-anchor" href="#_5-session-契约" aria-label="Permalink to &quot;5. Session 契约&quot;">​</a></h2><p><code>semantics=session</code> 的 Tool 通过同一 invoke route 接纳，返回 HTTP 202 与 invocation ID。 Status/result 使用通用 <code>/invocations/{id}</code> routes；有所有权的 Session 通过 <code>POST /invocations/{id}/stop</code> 停止。</p><p>PAOS 将 Session ownership 记为 <code>task</code>、<code>shared</code> 或 <code>runtime</code>。Task 只能停止自己拥有的 Session；shared Session 可跨 task finalize 存续；runtime-owned Session 由 Agent 外部管理。 非终态 task-owned Session 阻止 finalize，Runtime stop 也会计入全部活动 Session。</p><h2 id="_6-agent-tools" tabindex="-1">6. Agent tools <a class="header-anchor" href="#_6-agent-tools" aria-label="Permalink to &quot;6. Agent tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tool</th><th style="text-align:left;">契约</th></tr></thead><tbody><tr><td style="text-align:left;"><code>forge_tool_context</code></td><td style="text-align:left;">读取 ToolSpec 与实时 context。</td></tr><tr><td style="text-align:left;"><code>forge_tool_query</code></td><td style="text-align:left;">调用同步 Query，可作无任务诊断或绑定 <code>task_id</code>。</td></tr><tr><td style="text-align:left;"><code>forge_tool_start_action</code></td><td style="text-align:left;">为绑定的 <code>task_id</code> 接纳异步 Action。</td></tr><tr><td style="text-align:left;"><code>forge_tool_action_status</code></td><td style="text-align:left;">读取 invocation phase/status。</td></tr><tr><td style="text-align:left;"><code>forge_tool_action_result</code></td><td style="text-align:left;">读取 pending 或终态 result。</td></tr><tr><td style="text-align:left;"><code>forge_tool_cancel_action</code></td><td style="text-align:left;">请求取消，不宣称停止。</td></tr><tr><td style="text-align:left;"><code>forge_tool_start_session</code></td><td style="text-align:left;">以显式 ownership 接纳绑定 Session。</td></tr><tr><td style="text-align:left;"><code>forge_tool_session_status/result/stop_session</code></td><td style="text-align:left;">核对或停止有所有权的 Session。</td></tr><tr><td style="text-align:left;"><code>forge_task_create</code></td><td style="text-align:left;">创建唯一活动 AgentTask 与 revision 1。</td></tr><tr><td style="text-align:left;"><code>forge_task_get</code></td><td style="text-align:left;">读取 task、revisions、Tool records、evidence 与 verdict。</td></tr><tr><td style="text-align:left;"><code>forge_task_begin_revision</code></td><td style="text-align:left;">在允许 recovery verdict 后追加 revision。</td></tr><tr><td style="text-align:left;"><code>forge_task_finalize</code></td><td style="text-align:left;">后置采集并执行聚合任务验证。</td></tr><tr><td style="text-align:left;"><code>forge_task_cancel</code></td><td style="text-align:left;">取消非终态 Action，并停止 task-owned Session。</td></tr></tbody></table><p>无 Runtime 时仍提供诊断 context tool；受治理 tools 要求恰好一个健康活动 Skill Runtime。 现有通用 Agent tools 与动态 MCP tools 独立保持注册。</p><h2 id="_7-binding、identity-与关联" tabindex="-1">7. Binding、Identity 与关联 <a class="header-anchor" href="#_7-binding、identity-与关联" aria-label="Permalink to &quot;7. Binding、Identity 与关联&quot;">​</a></h2><p><code>activate_skill</code> 读取已安装工作流并预览当前 Runtime。创建 task 时重新校验 candidate，冻结 Skill 名称/版本、manifest 与工作流 hash、profile、Runtime instance、Gateway identity、所需 ToolSpec hash 与 Node artifact ID。每次执行都复核 allowlist、semantics、readiness、ToolSpec hash 和 Runtime identity。</p><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">所有者</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">稳定任务聚合</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">不可变规划世代</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">不可变 Skill/Runtime/ToolSpec 快照</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">绑定 Query、Action 或 Session record</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">admission 前持久化的幂等/关联身份</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">异步 Action 或 Session 生命周期</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">执行 attempt</td></tr></tbody></table><p>关联必须显式保存；这些 ID 不是别名，也不能相互派生。</p><h2 id="_8-agenttask-模型" tabindex="-1">8. AgentTask 模型 <a class="header-anchor" href="#_8-agenttask-模型" aria-label="Permalink to &quot;8. AgentTask 模型&quot;">​</a></h2><p>全局最多一个非终态 AgentTask；诊断 Query 不占槽位。创建与更新使用 SQLite WAL 和 immediate transaction。Task 包含只追加 PlanRevision；每个 revision 包含 Tool records、semantic verdict 和 verification attempts。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>executing</span></span>
<span class="line"><span>  ├─ finalize → succeeded | failed</span></span>
<span class="line"><span>  ├─ recovery verdict → awaiting_replan → begin_revision → executing</span></span>
<span class="line"><span>  └─ cancel → cancelling → reconcile → finalize → cancelled | failed</span></span></code></pre></div><p>Tool record 终结后，后续 observation 不改写执行事实。Recovery revision 保持相同 task ID， 并受 replan count 与 deadline 限制。</p><h2 id="_9-evidence-与-verification" tabindex="-1">9. Evidence 与 verification <a class="header-anchor" href="#_9-evidence-与-verification" aria-label="Permalink to &quot;9. Evidence 与 verification&quot;">​</a></h2><p>PAOS 在第一次绑定 Action 前和所有绑定 Action 达到记账终态后进行 best-effort 采集。Evidence artifact 包含 source、phase、sequence、timestamp、media metadata、size、SHA-256 与工作区相对 reference。采集错误会显式记录。Verifier 接收任务上下文前，会检查 bundle 身份、质量、采集时间 窗口、policy 要求以及保留 artifact 字节。</p><p><code>forge_task_finalize</code> 聚合全部绑定 Tool facts，并应用任务契约：</p><ul><li><code>off</code>：执行派生结果；</li><li><code>audit</code>：记录 semantic verdict，保留执行派生结果；</li><li><code>enforce</code>：semantic verdict 决定成功并 fail closed；</li><li><code>recovery</code>：enforce 语义加有预算 <code>replan_required</code>。</li></ul><p>Forge ToolResult 与 events 对执行负责；PAOS verifier 只判断用户任务是否完成。 它的上下文包含冻结的 Skill binding、PlanRevision、ToolExecutionRecord、Gateway 终态结果、 before/after evidence 和作用域建议 Lesson。</p><h2 id="_10-experience-与-evolution" tabindex="-1">10. Experience 与 evolution <a class="header-anchor" href="#_10-experience-与-evolution" aria-label="Permalink to &quot;10. Experience 与 evolution&quot;">​</a></h2><p>终态 AgentTask 转换为唯一去敏 episode，引用冻结的 Skill binding 与版本、PlanRevision verdict、 ToolInvocation/attempt fingerprint 和 evidence，但不会把原始 output、凭据、endpoint 或物理参数 写入学习内容。</p><p>Lesson 与 failure cluster 按绑定 Skill 版本限定。Evolution fail-open，不改变 Gateway facts、 AgentTask terminal state 或 verification attempt。</p><h2 id="_11-skill-runtime-与分发" tabindex="-1">11. Skill Runtime 与分发 <a class="header-anchor" href="#_11-skill-runtime-与分发" aria-label="Permalink to &quot;11. Skill Runtime 与分发&quot;">​</a></h2><p>Skill Runtime 安装并管理 manifest v2 Bundle。安装要求安全 contained path、有界解包、SHA-256 文件清单、严格 manifest、staging、原子替换与 rollback。每个 Node lock 固定 artifact ID、版本、 平台、架构、归档类型、根目录可执行文件名与 SHA-256。静态 index 下载条目包含 size 与 digest； Registry Node 下载以已验证的 Skill lock 为摘要权威，并在进入 cache 前从 Registry 元数据或直接 下载端点解析精确大小。安装始终显式触发，默认还需确认。</p><p>RuntimeManager 要求 <code>PATH</code> 中存在 Dora CLI（v0.4.1 与 <code>dora-message</code> v0.7.0 是当前 Forge Skill 兼容基线）。 它物化摘要覆盖 dataflow 路径与 profile 文件内容的环境，并将 <code>PAOS_SKILL_NAME</code> 与 <code>PAOS_SKILL_VERSION</code> 注入 Dora 进程环境及 dataflow 占位符。</p><p>启动时先持久化 <code>starting</code>；Bundle 含可选 <code>start.sh</code> 时，要求 Bash，并在 Dora 前以 <code>bash &lt;bundle&gt;/start.sh &lt;name&gt; &lt;version&gt;</code> 执行且继承终端 stdio。钩子成功后，RuntimeManager 需要时启动本地 Dora 服务，再启动命名 profile，等待 Gateway <code>/tools</code> 与 manifest 全部 required Tool context，并持久化 status/log。健康活动 Runtime 提供 Skill availability；其 manifest 是 Gateway URL 的唯一来源。按 Skill 的跨进程锁拒绝重叠生命周期变更。</p><p>存在被追踪非终态 invocation、Session 或 task binding 时，正常 stop 会被拒绝。Force stop 记录 audit event，且不改变执行事实。</p><p>PhyAgentOS 源码与 Python 分发不包含具体 Forge Skill、Node、模型或仿真资源。它们仅在本地测试 或部署时独立获取。打包工具生成确定性 Skill 归档，安装器在提交前完成验证。</p><h2 id="_12-conformance" tabindex="-1">12. Conformance <a class="header-anchor" href="#_12-conformance" aria-label="Permalink to &quot;12. Conformance&quot;">​</a></h2><p>接入需要覆盖 Tool discovery/context、Query response、Action/Session admission、pending/terminal result、cancel/stop、timeout/unknown、无 POST 重试恢复、endpoint concurrency、不可变 AgentTask binding/revisions、ownership、evidence、聚合 verification、按版本 experience、Bundle security、 事务安装、Runtime health、安全切换与 availability 传播。</p><p>Mock Gateway 测试可完成代码与契约验收；硬件/MuJoCo 验收单独记录确切 artifact digests 与环境。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/zh/01-framework-introduction">框架介绍</a></li><li><a href="/docs/zh/04-forge-configuration-reference">配置参考</a></li><li><a href="/docs/user_development_guide/README">集成开发指南</a></li><li><a href="/docs/user_manual/README">运行手册</a></li></ul>`,53)])])}const h=t(i,[["render",s]]);export{u as __pageData,h as default};
